{"command":"python3 << 'PY'
import os, subprocess, time, signal, sys

# Try simpler: fork, child execs ./executable directly, parent quickly reads maps before child exits
# ./executable /bin/ls will quickly exit, but we can make it process a large file to make it take some time? It processes 138KB, maybe still quick but we can catch.

pid=os.fork()
if pid==0:
    # child: exec executable
    os.execv("./executable", ["./executable","/bin/ls"])
    os._exit(0)
else:
    # parent: loop until child appears?
    for i in range(5):
        time.sleep(0.05)
        try:
            with open(f"/proc/{pid}/maps") as f:
                content=f.read()
                if "executable" in content:
                    print("found executable in maps!")
                    print(content[:2000])
                    break
                else:
                    print("maps content", content[:1000])
        except Exception as e:
            print("exception", e)
            # check if child still exists
            try:
                os.kill(pid,0)
                print("child still exists")
            except:
                print("child gone")
                break
    try:
        os.waitpid(pid,0)
    except:
        pass

